orbit.css:
.yy-action-art[data-action="orbit"] .origin-bottom{transform-origin:center bottom}
.yy-action-art[data-action="orbit"] .origin-center{transform-origin:center}
.yy-action-art[data-action="orbit"] [class~="[transform-box:fill-box]"]{transform-box:fill-box}
.yy-action-art[data-action="orbit"] [class~="origin-[150px_130px]"]{transform-origin:150px 130px}
.yy-action-art[data-action="orbit"] .fill-pupil-black{fill:#1a1a1a}
.yy-action-art[data-action="orbit"] .pointer-events-none{pointer-events:none}
.yy-action-art[data-action="orbit"] .w-full{width:100%}.yy-action-art[data-action="orbit"] .h-full{height:100%}.yy-action-art[data-action="orbit"] .overflow-visible{overflow:visible}


.yy-action-art[data-action="orbit"] .v13_hand_ball_shield-body {
  animation: yy-case-orbit-v13-hand-ball-shield-body 600ms cubic-bezier(0.18, 0.82, 0.14, 1) infinite;
  transform-box: view-box;
  transform-origin: 150px 170px;
}

.yy-action-art[data-action="orbit"] .v13_hand_ball_shield-hand-left {
  animation: yy-case-orbit-v13-hand-ball-shield-hand-left 250ms linear infinite;
